102	func (r *Reporter) writeState() error {
103		data, err := json.Marshal(r.state)
104		if err != nil {
105			return err
106		}
107		dir := filepath.Dir(r.path)
108		file, err := os.CreateTemp(dir, ".telemetry-*")
109		if err != nil {
110			return fmt.Errorf("creating telemetry state: %w", err)
111		}
112		defer os.Remove(file.Name())
113		if err := file.Chmod(0600); err != nil {
114			file.Close()
115			return err
116		}
117		if _, err := file.Write(data); err != nil {
118			file.Close()
119			return err
120		}
121		if err := file.Close(); err != nil {
122			return err
123		}
124		if err := os.Rename(file.Name(), r.path); err != nil {
125			return fmt.Errorf("writing telemetry state: %w", err)
126		}
127		return nil
128	}
