130	// Report sends one anonymous ping and persists the time only after delivery succeeds.
131	func (r *Reporter) Report(ctx context.Context) error {
132		r.mu.Lock()
133		defer r.mu.Unlock()
134		e := event{Event: "flipt.ping", AnonymousID: r.state.UUID}
135		e.Properties.UUID = r.state.UUID
136		e.Properties.Version = schemaVersion
137		e.Properties.Flipt.Version = r.version
138		data, err := json.Marshal(e)
139		if err != nil {
140			return err
141		}
142		req, err := http.NewRequestWithContext(ctx, http.MethodPost, r.endpoint, bytes.NewReader(data))
143		if err != nil {
144			return err
145		}
146		req.Header.Set("Content-Type", "application/json")
147		resp, err := r.client.Do(req)
148		if err != nil {
149			return fmt.Errorf("sending telemetry: %w", err)
150		}
151		defer resp.Body.Close()
152		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
153			return fmt.Errorf("sending telemetry: HTTP %d", resp.StatusCode)
154		}
155		previous := r.state.LastTimestamp
156		r.state.LastTimestamp = time.Now().UTC().Format(time.RFC3339)
157		if err := r.writeState(); err != nil {
158			r.state.LastTimestamp = previous
159			return err
160		}
161		return nil
162	}
