164	// Start begins a context-bound reporting loop. It returns without blocking the caller.
165	func (r *Reporter) Start(ctx context.Context) {
166		if r == nil {
167			return
168		}
169		go func() {
170			for {
171				r.mu.Lock()
172				last, err := time.Parse(time.RFC3339, r.state.LastTimestamp)
173				r.mu.Unlock()
174				delay := time.Duration(0)
175				if err == nil {
176					delay = time.Until(last.Add(reportInterval))
177				}
178				if delay > 0 {
179					timer := time.NewTimer(delay)
180					select {
181					case <-ctx.Done():
182						if !timer.Stop() {
183							select {
184							case <-timer.C:
185							default:
186							}
187						}
188						return
189					case <-timer.C:
190					}
191				}
192				if ctx.Err() != nil {
193					return
194				}
195				if err := r.Report(ctx); err != nil {
196					r.logger.Warnf("reporting telemetry: %v", err)
197				}
198				// A failed report should not spin. Retry on the next interval.
199				timer := time.NewTimer(reportInterval)
200				select {
201				case <-ctx.Done():
202					if !timer.Stop() {
203						select {
204						case <-timer.C:
205						default:
206						}
207					}
208					return
209				case <-timer.C:
210				}
211			}
212		}()
213	}
